import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

interface ApiError {
  error: { code: string; message: string };
}

async function postTitle(server: Running, title: unknown): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
}

async function listTitles(server: Running): Promise<string[]> {
  const body = (await (await fetch(`${server.baseUrl}/api/tasks`)).json()) as { tasks: Task[] };
  return body.tasks.map((task) => task.title);
}

async function assertRejected(server: Running, title: unknown, message: string): Promise<void> {
  const before = await listTitles(server);
  const response = await postTitle(server, title);
  assert.equal(response.status, 400);
  const body = (await response.json()) as ApiError;
  assert.deepEqual(body, { error: { code: "validation_failed", message } });
  assert.deepEqual(await listTitles(server), before, "nothing was stored");
}

describe("SL-004 reject empty and over-long titles", () => {
  let server: Running;
  let html: string;
  let script: string;

  before(async () => {
    server = await startServer();
    html = await (await fetch(`${server.baseUrl}/`)).text();
    script = await (await fetch(`${server.baseUrl}/app.js`)).text();
  });
  after(async () => {
    await server?.stop();
  });

  describe("AC-1: a title that is empty after trimming", () => {
    it("AC-1: an empty title answers 400 'A title is required.' and stores nothing", async () => {
      await assertRejected(server, "", "A title is required.");
    });

    it("AC-1: a title of only spaces, tabs and line breaks is rejected the same way", async () => {
      await assertRejected(server, "   \t\n  ", "A title is required.");
    });

    it("AC-1: a title that is not a string is rejected with a validation error", async () => {
      await assertRejected(server, 42, "Title must be a string.");
      await assertRejected(server, null, "Title must be a string.");
    });

    it("AC-1: the page has a role=alert element to explain the reason", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    });

    it("AC-1: the page script shows the server's error message with textContent", () => {
      assert.match(script, /form-message/);
      assert.match(script, /error\.message/);
      assert.doesNotMatch(script, /innerHTML/);
    });

    it("AC-1: the page script clears the field only when the task was created", () => {
      assert.match(script, /response\.ok/);
    });
  });

  describe("AC-2: a title longer than 500 characters", () => {
    const tooLong = "The title is too long (maximum 500 characters).";

    it("AC-2: 501 characters answers 400 and stores nothing", async () => {
      await assertRejected(server, "a".repeat(501), tooLong);
    });

    it("AC-2: the length is counted after trimming, so 501 characters with padding is rejected", async () => {
      await assertRejected(server, `  ${"a".repeat(501)}  `, tooLong);
    });

    it("AC-2: exactly 500 characters is accepted", async () => {
      const response = await postTitle(server, "b".repeat(500));
      assert.equal(response.status, 201);
      assert.ok((await listTitles(server)).includes("b".repeat(500)));
    });

    it("AC-2: 500 characters plus outer spaces is accepted and stored trimmed", async () => {
      const response = await postTitle(server, ` ${"c".repeat(500)} `);
      assert.equal(response.status, 201);
      assert.ok((await listTitles(server)).includes("c".repeat(500)));
    });

    it("AC-2: after a rejection, a corrected title is added normally", async () => {
      await assertRejected(server, "", "A title is required.");
      const response = await postTitle(server, "Corrected");
      assert.equal(response.status, 201);
      assert.ok((await listTitles(server)).includes("Corrected"));
    });
  });
});
EOF
